-- Only explicitly reviewed, bounded copies are captured by standard replication.
CREATE TABLE catalog_publications(id uuid PRIMARY KEY,revision integer NOT NULL CHECK(revision>0),projection jsonb NOT NULL CHECK(octet_length(projection::text)<=8000),source_digest text NOT NULL);
CREATE UNIQUE INDEX catalog_one_current_subject_publication ON catalog_publications ((projection->'body'->'subject'->>'offeringId'),(COALESCE(projection->'body'->'subject'->>'variantId',''))) WHERE projection->>'status'='published';
CREATE TABLE catalog_publication_history(id uuid NOT NULL,revision integer NOT NULL,projection jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id,revision));
CREATE FUNCTION catalog_publication_capture_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.id<>OLD.id OR NEW.revision<=OLD.revision) THEN RAISE EXCEPTION 'Publication revision must increase'; END IF; INSERT INTO catalog_publication_history(id,revision,projection) VALUES(NEW.id,NEW.revision,NEW.projection); RETURN NEW; END $$;
CREATE TRIGGER catalog_publication_history_capture AFTER INSERT OR UPDATE ON catalog_publications FOR EACH ROW EXECUTE FUNCTION catalog_publication_capture_history();
CREATE TRIGGER catalog_publication_history_immutable BEFORE UPDATE OR DELETE ON catalog_publication_history FOR EACH ROW EXECUTE FUNCTION catalog_external_append_only();

CREATE FUNCTION catalog_publication_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Publication history cannot be deleted'; END IF; IF NEW.id<>OLD.id OR NEW.revision<>OLD.revision+1 OR NEW.source_digest<>OLD.source_digest OR OLD.projection->>'status'<>'published' OR NEW.projection->>'status'<>'withdrawn' OR (NEW.projection-ARRAY['revision','status','withdrawnAt','withdrawalReason'])<>(OLD.projection-ARRAY['revision','status','withdrawnAt','withdrawalReason']) THEN RAISE EXCEPTION 'Reviewed publication terms are immutable; only withdrawal is allowed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER catalog_publication_terms_immutable BEFORE UPDATE OR DELETE ON catalog_publications FOR EACH ROW EXECUTE FUNCTION catalog_publication_guard();
